1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	/** An item a customer brings to be insured, as the office records it. */
6	export interface Item {
7	  type: string;
8	  material?: string;
9	  cursed?: boolean;
10	  enchantment?: number;
11	}
12	
13	const PROCESSING_FEE = 5;
14	
15	/**
16	 * How the office classes an item on its price list. Main items each have a row of
17	 * their own; components share a single uniform rate, and the office's
18	 * building-block offer is written for components alone.
19	 */
20	type PriceListClass = "main item" | "component";
21	
22	/** One row of the MHPCO price list: what the office charges to insure one such item. */
23	interface PriceListEntry {
24	  class: PriceListClass;
25	  basePremium: number;
26	  insuranceValue: number;
27	}
28	
29	const COMPONENT_BASE_PREMIUM = 25;
30	const COMPONENT_INSURANCE_VALUE = 250;
31	
32	/**
33	 * The MHPCO price list, as posted at the counter: every kind of item the office
34	 * recognises, and what it charges for one of them. An item type absent from the
35	 * list is one the office does not insure.
36	 */
37	const PRICE_LIST: Record<string, PriceListEntry> = {
38	  sword: { class: "main item", basePremium: 100, insuranceValue: 1000 },
39	  amulet: { class: "main item", basePremium: 60, insuranceValue: 600 },
40	  staff: { class: "main item", basePremium: 80, insuranceValue: 800 },
41	  potion: { class: "main item", basePremium: 40, insuranceValue: 400 },
42	  rune: {
43	    class: "component",
44	    basePremium: COMPONENT_BASE_PREMIUM,
45	    insuranceValue: COMPONENT_INSURANCE_VALUE,
46	  },
47	  moonstone: {
48	    class: "component",
49	    basePremium: COMPONENT_BASE_PREMIUM,
50	    insuranceValue: COMPONENT_INSURANCE_VALUE,
51	  },
52	};
53	
54	/** The price list's row for the given item type. */
55	function priceListEntryOf(type: string): PriceListEntry {
56	  const entry = PRICE_LIST[type];
57	  if (entry === undefined) {
58	    throw new Error(`the MHPCO price list does not cover a ${type}`);
59	  }
60	  return entry;
61	}
62	
63	function isComponentType(type: string): boolean {
64	  return priceListEntryOf(type).class === "component";
65	}
66	
67	/** The price-list base premium for one item of the given type. */
68	function catalogueBasePremiumOf(type: string): number {
69	  return priceListEntryOf(type).basePremium;
70	}
71	
72	const BLOCK_SIZE = 3;
73	const BLOCK_BASE_PREMIUM = 60;
74	
75	/** A policy's items of one and the same type -- what the office calls "alike". */
76	interface AlikeItems {
77	  type: string;
78	  items: Item[];
79	}
80	
81	/**
82	 * The office groups a policy's items into groups of alike items, because its
83	 * building-block offer is priced per group rather than per item. "Alike" means
84	 * the same item type.
85	 */
86	function groupAlikeItems(items: Item[]): AlikeItems[] {
87	  const groups = new Map<string, AlikeItems>();
88	  for (const item of items) {
89	    const group = groups.get(item.type);
90	    if (group === undefined) {
91	      groups.set(item.type, { type: item.type, items: [item] });
92	    } else {
93	      group.items.push(item);
94	    }
95	  }
96	  return [...groups.values()];
97	}
98	
99	/**
100	 * A building block of exactly 3 alike components is offered at a special base
101	 * premium instead of the catalogue rate; any other count is priced per component.
102	 */
103	function isBuildingBlock({ type, items }: AlikeItems): boolean {
104	  return isComponentType(type) && items.length === BLOCK_SIZE;
105	}
106	
107	/** Without an offer, the office simply charges the catalogue rate for every item. */
108	function catalogueRateBasePremiumOf({ type, items }: AlikeItems): number {
109	  return items.length * catalogueBasePremiumOf(type);
110	}
111	
112	/** What the office charges for one group of alike items covered by the same policy. */
113	function alikeItemsBasePremiumOf(alikeItems: AlikeItems): number {
114	  return isBuildingBlock(alikeItems)
115	    ? BLOCK_BASE_PREMIUM
116	    : catalogueRateBasePremiumOf(alikeItems);
117	}
118	
119	const HIGH_ENCHANTMENT_LEVEL = 5;
120	
121	function isCursed(item: Item): boolean {
122	  return item.cursed === true;
123	}
124	
125	/** The office considers an item highly enchanted from enchantment level 5 upwards. */
126	function isHighlyEnchanted(item: Item): boolean {
127	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
128	}
129	
130	/**
131	 * One clause of the office's risk schedule: the risk it looks for in a single
132	 * item, and the surcharge it levies on that item's base premium when it finds it.
133	 */
134	interface ItemRiskClause {
135	  appliesTo: (item: Item) => boolean;
136	  surchargeRate: number;
137	}
138	
139	/** The office's schedule of item-specific risks, as written in its statutes. */
140	const ITEM_RISK_CLAUSES: ItemRiskClause[] = [
141	  { appliesTo: isCursed, surchargeRate: 0.5 },
142	  { appliesTo: isHighlyEnchanted, surchargeRate: 0.3 },
143	];
144	
145	/**
146	 * Item-specific risk surcharges are charged on the base premium of the affected
147	 * item alone, never on the policy total. An item that carries several risks is
148	 * surcharged for each of them, the office adding the rates together.
149	 */
150	function itemRiskSurchargeRateOf(item: Item): number {
151	  return ITEM_RISK_CLAUSES.filter((clause) => clause.appliesTo(item)).reduce(
152	    (rate, clause) => rate + clause.surchargeRate,
153	    0,
154	  );
155	}
156	
157	/**
158	 * How much of a group's base premium each alike item is held to carry. Group
159	 * offers such as the building block are priced per group, so the office has to
160	 * decide what an individual item inside a group is worth before it can charge an
161	 * item-specific surcharge on it. The office's reading: alike items are
162	 * interchangeable, so each carries an equal share of the group's base premium
163	 * (20 G each inside a 60 G block). Shares are kept as exact fractions.
164	 */
165	function apportionedBasePremiumOf(alikeItems: AlikeItems): number {
166	  return alikeItemsBasePremiumOf(alikeItems) / alikeItems.items.length;
167	}
168	
169	/** One item paired with the base premium the office holds it to carry. */
170	interface ItemBasePremium {
171	  item: Item;
172	  basePremium: number;
173	}
174	
175	/** What each item of a group contributes to the policy base premium. */
176	function itemBasePremiumsOf(alikeItems: AlikeItems): ItemBasePremium[] {
177	  const basePremium = apportionedBasePremiumOf(alikeItems);
178	  return alikeItems.items.map((item) => ({ item, basePremium }));
179	}
180	
181	/** What an item's own risks add to its base premium, in G. */
182	function itemRiskSurchargeOf({ item, basePremium }: ItemBasePremium): number {
183	  return basePremium * itemRiskSurchargeRateOf(item);
184	}
185	
186	/**
187	 * How the office rates the items of one policy. The two quantities are kept
188	 * apart because the office rates its policy-wide terms against one of them and
189	 * not the other: the policy base premium is their rating basis, while item risk
190	 * surcharges ride on top of it untouched by any policy-wide term.
191	 */
192	interface ItemRating {
193	  policyBasePremium: number;
194	  itemRiskSurcharges: number;
195	}
196	
197	/**
198	 * The item side of the premium: it depends on the items alone and knows nothing
199	 * of who brings them.
200	 */
201	function itemRatingOf(items: Item[]): ItemRating {
202	  const itemBasePremiums = groupAlikeItems(items).flatMap(itemBasePremiumsOf);
203	  return {
204	    policyBasePremium: itemBasePremiums.reduce((total, { basePremium }) => total + basePremium, 0),
205	    itemRiskSurcharges: itemBasePremiums.reduce(
206	      (total, itemBasePremium) => total + itemRiskSurchargeOf(itemBasePremium),
207	      0,
208	    ),
209	  };
210	}
211	
212	const LOYALTY_DISCOUNT_RATE = -0.2;
213	const LOYALTY_YEARS = 2;
214	
215	/** The office calls a customer long-standing after 2 years of business. */
216	function isLongStandingCustomer(customer: Customer): boolean {
217	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
218	}
219	
220	/**
221	 * Everything the office knows when it rates the policy-wide terms of one
222	 * contract: the customer it is writing for, and its own history of contracts
223	 * already written for them. Terms are earned by either, so a clause of the
224	 * office's schedule is rated against the pair rather than against one of them.
225	 */
226	interface PolicyCircumstances {
227	  customer: Customer;
228	  contractsAlreadyWritten: number;
229	}
230	
231	/**
232	 * The office grants its follow-up discount on each contract it writes for a
233	 * customer after their first, so the term is earned by the contracts already
234	 * written rather than by the customer's record.
235	 */
236	function isFollowUpContract({ contractsAlreadyWritten }: PolicyCircumstances): boolean {
237	  return contractsAlreadyWritten > 0;
238	}
239	
240	/**
241	 * One clause of the office's schedule of policy-wide terms: the circumstances it
242	 * looks for in the contract before it, and the rate it then applies to the policy
243	 * base premium. Surcharges carry a positive rate, discounts a negative one -- the
244	 * office's own arithmetic, which adds its policy-wide rates together.
245	 */
246	interface PolicyModifierClause {
247	  appliesTo: (circumstances: PolicyCircumstances) => boolean;
248	  modifierRate: number;
249	}
250	
251	/**
252	 * Each quoted item is a first insurance whatever the customer's history, so the
253	 * office's initial assessment is earned by no record and withheld from none --
254	 * the one scheduled term whose circumstances are always met.
255	 */
256	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
257	
258	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
259	
260	/**
261	 * The office's schedule of policy-wide terms: the initial assessment it levies on
262	 * every contract it writes, what a long-standing record entitles the customer to,
263	 * and what the standing of this contract in their history grants them.
264	 */
265	const POLICY_MODIFIER_CLAUSES: PolicyModifierClause[] = [
266	  { appliesTo: () => true, modifierRate: FIRST_INSURANCE_SURCHARGE_RATE },
267	  {
268	    appliesTo: ({ customer }) => isLongStandingCustomer(customer),
269	    modifierRate: LOYALTY_DISCOUNT_RATE,
270	  },
271	  { appliesTo: isFollowUpContract, modifierRate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
272	];
273	
274	/**
275	 * Every policy-wide term the office rates on the policy base premium -- the sum of
276	 * all item base premiums -- never on a single item: whichever scheduled terms the
277	 * circumstances of this contract earn, the office adding their rates together.
278	 */
279	function policyModifierRateOf(circumstances: PolicyCircumstances): number {
280	  return POLICY_MODIFIER_CLAUSES.filter((clause) => clause.appliesTo(circumstances)).reduce(
281	    (rate, clause) => rate + clause.modifierRate,
282	    0,
283	  );
284	}
285	
286	/**
287	 * What the items and the contract's circumstances come to before the office writes
288	 * the figure down: what the items themselves are worth, adjusted by the policy-wide
289	 * terms the circumstances earn, with the processing fee added at the very end. Kept
290	 * as an exact fraction -- the office rounds the premium and nothing on the way to it.
291	 */
292	function exactPolicyPremiumOf(itemRating: ItemRating, circumstances: PolicyCircumstances): number {
293	  const { policyBasePremium, itemRiskSurcharges } = itemRating;
294	  const modifierRate = policyModifierRateOf(circumstances);
295	  return (
296	    policyBasePremium + itemRiskSurcharges + policyBasePremium * modifierRate + PROCESSING_FEE
297	  );
298	}
299	
300	/**
301	 * Which way money moves across the office's counter. The office's favour is one
302	 * principle for all its amounts, but which way it rounds an amount follows from
303	 * this: a fraction kept is a fraction the office gains.
304	 */
305	type DirectionOfPayment = "owed to the office" | "handed out by the office";
306	
307	/**
308	 * The office writes whole G. Its one rounding principle -- "all amounts are rounded
309	 * to whole G in the MHPCO's favor" -- settles every fraction in its own favour, which
310	 * means keeping the fraction: an amount owed to it rounds up, an amount it hands out
311	 * rounds down. The direction of payment is the only thing that varies between its
312	 * amounts, so each kind of amount declares that and nothing else.
313	 */
314	function roundedInMHPCOsFavour(exactAmount: number, direction: DirectionOfPayment): number {
315	  return direction === "owed to the office" ? Math.ceil(exactAmount) : Math.floor(exactAmount);
316	}
317	
318	/** A premium is money owed to the office, so its fraction is rounded up. */
319	function premiumRoundedInMHPCOsFavour(exactPremium: number): number {
320	  return roundedInMHPCOsFavour(exactPremium, "owed to the office");
321	}
322	
323	/**
324	 * The premium the office charges for covering those items under this contract: what
325	 * the terms come to, rounded to whole G in the office's favour. The office quotes
326	 * whole G, so rounding is part of the premium it decides on and not a later dressing
327	 * up of the figure.
328	 */
329	function policyPremiumOf(itemRating: ItemRating, circumstances: PolicyCircumstances): number {
330	  return premiumRoundedInMHPCOsFavour(exactPolicyPremiumOf(itemRating, circumstances));
331	}
332	
333	/**
334	 * The insurance sum of a list of items: what the price list says they are insured
335	 * for. A reading of the price list and nothing more -- premium offers and
336	 * surcharges do not touch it.
337	 */
338	function insuranceSumOf(items: Item[]): number {
339	  return items.reduce((sum, item) => sum + priceListEntryOf(item.type).insuranceValue, 0);
340	}
341	
342	/**
343	 * The office will pay out at most twice the insurance sum on one policy, all
344	 * claims together. A statute of the office, rated on the insurance sum and on
345	 * nothing else -- no premium term raises or lowers it.
346	 */
347	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
348	
349	/**
350	 * The insured item one reported damage is settled against, struck off the items
351	 * still covered: every damage event in a report is a separate claim on a separate
352	 * insured item, so the office refuses a report that claims more of a kind than the
353	 * policy covers.
354	 */
355	function claimAgainst(stillCovered: Item[], damage: Damage): Item {
356	  if (damage.amount < 0) {
357	    throw new Error(`a damage cannot be negative, but ${damage.amount} G was reported`);
358	  }
359	  const insured = stillCovered.findIndex((item) => item.type === damage.itemType);
360	  if (insured < 0) {
361	    throw new Error(`the policy does not cover a damaged ${damage.itemType}`);
362	  }
363	  return stillCovered.splice(insured, 1)[0];
364	}
365	
366	/**
367	 * A policy the office has written: the items it covers, and how much of its payout
368	 * cap is still available. The cap is the policy's own ledger -- it opens at the
369	 * capped amount the office's statute allows for these items, and only the policy
370	 * itself may draw it down -- so the office reads what remains rather than keeping
371	 * that figure for it.
372	 */
373	class Policy {
374	  /**
375	   * The part of this policy's cap the office has not yet handed out. Never
376	   * negative: the office only ever draws off a payout its cap statute has already
377	   * limited to this figure, so the ledger cannot be overdrawn.
378	   */
379	  private cap: number;
380	
381	  constructor(readonly items: Item[]) {
382	    this.cap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items);
383	  }
384	
385	  get remainingCap(): number {
386	    return this.cap;
387	  }
388	
389	  /**
390	   * Settling one damage report against this policy: the office pays what its
391	   * statutes allow on the report, draws that off the cap, and reports both.
392	   */
393	  settle(incident: Incident): Settlement {
394	    const payout = this.cappedPayoutFor(incident);
395	    this.cap -= payout;
396	    return { payout, remainingCap: this.cap };
397	  }
398	
399	  /**
400	   * What the office pays out on one damage report once its cap statute has had its
401	   * say: the clauses decide what the damage is worth, and the cap decides how much
402	   * of that the office is still willing to hand out under this policy. The cap is
403	   * a limit on the total of all claims, so what limits this one is the part of it
404	   * still open -- a policy already paid up to its cap pays nothing more.
405	   */
406	  private cappedPayoutFor(incident: Incident): number {
407	    return Math.min(this.payoutFor(incident), this.cap);
408	  }
409	
410	  /** What the office pays out on one damage report, over all the items damaged. */
411	  private payoutFor(incident: Incident): number {
412	    const stillCovered = [...this.items];
413	    const exactPayout = incident.damages.reduce(
414	      (payout, damage) => payout + reimbursementFor(damage, claimAgainst(stillCovered, damage)),
415	      0,
416	    );
417	    return payoutRoundedInMHPCOsFavour(exactPayout);
418	  }
419	}
420	
421	/** What a damage report costs the office, and what is left of the policy's cap. */
422	export interface Settlement {
423	  payout: number;
424	  remainingCap: number;
425	}
426	
427	/** One item damaged in an incident, as the customer reports it. */
428	export interface Damage {
429	  itemType: string;
430	  amount: number;
431	}
432	
433	/** A damage report against one policy. */
434	export interface Incident {
435	  cause: string;
436	  damages: Damage[];
437	}
438	
439	const DEDUCTIBLE_PER_DAMAGE = 100;
440	
441	/**
442	 * A payout is money the office hands out, so its fraction is rounded down. Only the
443	 * final payout is rounded; the clauses before it keep their fractions.
444	 */
445	function payoutRoundedInMHPCOsFavour(exactPayout: number): number {
446	  return roundedInMHPCOsFavour(exactPayout, "handed out by the office");
447	}
448	
449	/**
450	 * The office's half-reimbursement clause has an enchantment threshold of its own,
451	 * set higher than the threshold of the high-enchantment risk surcharge it charges
452	 * on premiums (level 5). Two statutes, written separately and free to move
453	 * separately: this one decides what the office pays out on a claim, that one what
454	 * it charges to write the policy.
455	 */
456	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
457	const HALF_REIMBURSEMENT_RATE = 0.5;
458	
459	/**
460	 * Damage to an item enchanted to level 8 or above the office reimburses at half,
461	 * holding the enchantment itself partly to blame for what befell the item.
462	 */
463	function qualifiesForHalfReimbursement(item: Item): boolean {
464	  return (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
465	}
466	
467	/**
468	 * Full reimbursement is the office's default: absent a clause that reduces it, a
469	 * damage is reimbursed in whole, less the excess. This is also what the office's
470	 * dragon-material clause ("damage to items made of dragon material is fully
471	 * reimbursed") amounts to -- it claims no more than every insured item already
472	 * gets, and where it meets the half-reimbursement clause the office has ruled that
473	 * the half-reimbursement clause wins. So dragon material earns the default and
474	 * overrides nothing, and the office reads no material to settle a claim.
475	 */
476	const FULL_REIMBURSEMENT_RATE = 1;
477	
478	/** The share of a damage the office reimburses before it deducts its excess. */
479	function reimbursedShareOf(item: Item): number {
480	  return qualifiesForHalfReimbursement(item)
481	    ? HALF_REIMBURSEMENT_RATE
482	    : FULL_REIMBURSEMENT_RATE;
483	}
484	
485	/**
486	 * What the office reimburses for one damaged item: the share its clauses allow,
487	 * less its excess on every damage event. A damage no larger than the excess is
488	 * absorbed by it entirely and reimbursed at nothing.
489	 */
490	function reimbursementFor(damage: Damage, item: Item): number {
491	  const reimbursed = damage.amount * reimbursedShareOf(item);
492	  return Math.max(reimbursed - DEDUCTIBLE_PER_DAMAGE, 0);
493	}
494	
495	/**
496	 * The office as a going concern: it serves one customer for the length of a
497	 * scenario, remembers the contracts it has already written for them -- its
498	 * follow-up discount depends on that history -- and the policies it issued, so
499	 * that later claims can be settled against them.
500	 */
501	export class ClaimOffice {
502	  private readonly policies: Policy[] = [];
503	
504	  constructor(private readonly customer: Customer) {}
505	
506	  quote(items: Item[]): number {
507	    const premium = policyPremiumOf(itemRatingOf(items), {
508	      customer: this.customer,
509	      contractsAlreadyWritten: this.policies.length,
510	    });
511	    this.policies.push(new Policy(items));
512	    return premium;
513	  }
514	
515	  /** Settling a damage report against one of the office's policies. */
516	  claim(policyIndex: number, incident: Incident): Settlement {
517	    return this.policies[policyIndex].settle(incident);
518	  }
519	}
520	
521	/** A customer's first and only contract with the office. */
522	export function quote(customer: Customer, items: Item[]): number {
523	  return new ClaimOffice(customer).quote(items);
524	}
